import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';

/**
 * firestore-min.rules is the comment-free copy of firestore.rules that gets
 * pasted into the Firebase console. It is generated by
 * scripts/build_min_rules.mjs and must never drift from the real file again
 * (the hand-maintained copy once missed three collections and kept weaker
 * access checks). These tests fail CI when the two disagree.
 */

const ROOT = resolve(process.cwd());
const rules = readFileSync(resolve(ROOT, 'firestore.rules'), 'utf8');

describe('firestore-min.rules', () => {
  it('is regenerated whenever firestore.rules changes', () => {
    // Throws (non-zero exit) when the minified copy is out of date.
    const out = execFileSync(process.execPath, [resolve(ROOT, 'scripts/build_min_rules.mjs'), '--check'], {
      encoding: 'utf8',
    });
    expect(out).toContain('in sync');
  });
});

describe('firestore.rules access guards', () => {
  // The rules engine matches the WHOLE string, so this RegExp mirrors the
  // pattern with ^…$ anchors to pin which addresses count as teachers.
  const source = /request\.auth\.token\.email\.matches\('([^']+)'\)/.exec(rules)?.[1] ?? '';
  const teacherPattern = new RegExp(`^${source}$`);

  it('grants the teacher role on the email DOMAIN only', () => {
    expect(source).not.toBe('');
    expect(teacherPattern.test('you@school.edu.kh')).toBe(true);
    expect(teacherPattern.test('teacher@university.edu')).toBe(true);
    expect(teacherPattern.test('Teacher@School.EDU.KH')).toBe(true);
    expect(teacherPattern.test('ms.dara@education.gov.kh')).toBe(true);
    // "edu" in the mailbox name of a free provider must NOT qualify.
    expect(teacherPattern.test('eduardo@gmail.com')).toBe(false);
    expect(teacherPattern.test('my.edu.account@outlook.com')).toBe(false);
    expect(teacherPattern.test('jane@gmail.com')).toBe(false);
  });

  it('does not let any verified user update a class they do not own', () => {
    const classesBlock = rules.slice(rules.indexOf('match /classes/{classId}'), rules.indexOf('match /enrollments/{studentUid}'));
    expect(classesBlock).not.toMatch(/allow create, update: if isVerifiedUser\(\);/);
    expect(classesBlock).toMatch(/allow update: if isVerifiedUser\(\)\s+&& resource\.data\.teacherUid == request\.auth\.uid/);
  });
});
